<script setup>
import { computed, defineAsyncComponent, nextTick, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { domainMap, serviceMap } from '@/config/navigation.js'
import { useServicePreferences } from '@/utils/servicePreferences.js'
import { getEnrollmentStats, getStudentStats } from '@/api/base.js'

const props = defineProps({ serviceKey: { type: String, required: true } })
const AnalyticsChart = defineAsyncComponent(() => import('@/components/business/AnalyticsChart.vue'))
const router = useRouter()
const { recordRecent } = useServicePreferences()
const service = computed(() => serviceMap[props.serviceKey])
const domain = computed(() => domainMap[service.value?.domain])
recordRecent(props.serviceKey)

const keyword=ref(''); const statusFilter=ref('all'); const moreFilters=ref(false); const detailVisible=ref(false); const formVisible=ref(false); const guideVisible=ref(false); const selectedRecord=ref(null); const calendarView=ref('week'); const scheduleFilter=ref('all'); const approvalTab=ref('mine'); const approvalComment=ref(''); const period=ref('year'); const analyticsDepartment=ref('all'); const formData=reactive({title:'',category:'normal',description:'',date:''}); const chatInput=ref(''); const chatMessages=ref([]); const aiThinking=ref(false); const activeChat=ref(1); const messageArea=ref(null)

