const primaryLabel=computed(()=>primaryLabels[service.value.template]); const primaryIcon=computed(()=>service.value.template==='analytics'?'Download':'Plus'); const dialogTitle=computed(()=>`${primaryLabel.value} · ${service.value.title}`)
const templateMetrics=computed(()=>[{label:'总量',value:service.value.template==='analytics'?'12,648':'128',note:'当前统计范围',icon:'DataBoard',color:'#3973b7',soft:'#eaf2fb'},{label:'进行中',value:'16',note:'较昨日 +2',icon:'Loading',color:'#c77800',soft:'#fff4df'},{label:'已完成',value:'96',note:'完成率 87.5%',icon:'CircleCheck',color:'#16865b',soft:'#e8f5ef'},{label:'待关注',value:'8',note:'其中 2 项紧急',icon:'Warning',color:'#c2413b',soft:'#fcebea'}])
const tableRows=ref([{code:'SC-2026-0018',name:`${service.value.title}示例记录 A`,category:'常规业务',owner:'张老师',status:'正常',updated:'2026-07-16 10:24'},{code:'SC-2026-0017',name:`${service.value.title}示例记录 B`,category:'重点业务',owner:'李老师',status:'待处理',updated:'2026-07-16 09:48'},{code:'SC-2026-0016',name:'2026 年度数据核验任务',category:'数据维护',owner:'王老师',status:'已完成',updated:'2026-07-15 17:36'},{code:'SC-2026-0015',name:'第二季度业务资料归档',category:'常规业务',owner:'赵老师',status:'正常',updated:'2026-07-15 14:12'},{code:'SC-2026-0014',name:'历史数据补充与校验',category:'数据维护',owner:'陈老师',status:'待处理',updated:'2026-07-14 16:05'}])
const filteredRows=computed(()=>tableRows.value.filter(row=>(statusFilter.value==='all'||row.status===statusFilter.value)&&(!keyword.value||`${row.code}${row.name}${row.owner}`.includes(keyword.value))))
const approvalTabs=[{key:'mine',label:'我的待办',count:6},{key:'submitted',label:'我发起的',count:3},{key:'done',label:'已处理',count:18},{key:'all',label:'全部事项',count:27}]
