const sendPrompt=async(prompt)=>{const text=prompt?.trim();if(!text||aiThinking.value)return;chatMessages.value.push({id:Date.now(),role:'user',text,time:'刚刚'});chatInput.value='';aiThinking.value=true;await nextTick();messageArea.value?.scrollTo({top:messageArea.value.scrollHeight,behavior:'smooth'});setTimeout(()=>{chatMessages.value.push({id:Date.now()+1,role:'assistant',text:`这是演示模式下针对“${text}”生成的示例答复。接入 AI Profile 后，这里会结合当前业务数据和已授权材料返回更具体的分析结果。`,time:'刚刚'});aiThinking.value=false;nextTick(()=>messageArea.value?.scrollTo({top:messageArea.value.scrollHeight,behavior:'smooth'}))},700)}
</script>

